-- NEST CRM baseline schema (Milestone 1).
-- UUID keys are generated by the application. Timestamps are stored in UTC (timestamptz).

CREATE TABLE workspaces (
    id         UUID PRIMARY KEY,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    name       TEXT NOT NULL,
    timezone   TEXT NOT NULL
);

CREATE TABLE users (
    id            UUID PRIMARY KEY,
    created_at    TIMESTAMPTZ NOT NULL,
    updated_at    TIMESTAMPTZ NOT NULL,
    workspace_id  UUID NOT NULL REFERENCES workspaces (id),
    email         TEXT NOT NULL,
    password_hash TEXT,
    role          TEXT NOT NULL,
    status        TEXT NOT NULL,
    display_name  TEXT,
    CONSTRAINT uq_users_email UNIQUE (email)
);
CREATE INDEX ix_users_workspace ON users (workspace_id);

CREATE TABLE leads (
    id                 UUID PRIMARY KEY,
    created_at         TIMESTAMPTZ NOT NULL,
    updated_at         TIMESTAMPTZ NOT NULL,
    workspace_id       UUID NOT NULL REFERENCES workspaces (id),
    owner_id           UUID NOT NULL REFERENCES users (id),
    name               TEXT NOT NULL,
    email              TEXT,
    phone              TEXT,
    source             TEXT,
    stage              TEXT NOT NULL,
    purpose            TEXT,
    budget_aed         NUMERIC(18, 2),
    bedrooms           INTEGER,
    emirate            TEXT,
    community          TEXT,
    purchase_timeframe TEXT,
    stated_intent      TEXT,
    sample             BOOLEAN NOT NULL DEFAULT FALSE,
    archived_at        TIMESTAMPTZ,
    version            BIGINT NOT NULL DEFAULT 0
);
CREATE INDEX ix_leads_workspace_stage ON leads (workspace_id, stage);
CREATE INDEX ix_leads_workspace_archived ON leads (workspace_id, archived_at);
CREATE INDEX ix_leads_workspace_email ON leads (workspace_id, LOWER(email));

CREATE TABLE lead_requirements (
    id                  UUID PRIMARY KEY,
    created_at          TIMESTAMPTZ NOT NULL,
    updated_at          TIMESTAMPTZ NOT NULL,
    lead_id             UUID NOT NULL REFERENCES leads (id) ON DELETE CASCADE,
    must_have_amenities JSONB,
    preferences         JSONB,
    provenance          TEXT,
    CONSTRAINT uq_lead_requirements_lead UNIQUE (lead_id)
);

CREATE TABLE interactions (
    id                 UUID PRIMARY KEY,
    created_at         TIMESTAMPTZ NOT NULL,
    updated_at         TIMESTAMPTZ NOT NULL,
    lead_id            UUID NOT NULL REFERENCES leads (id) ON DELETE CASCADE,
    workspace_id       UUID NOT NULL REFERENCES workspaces (id),
    type               TEXT NOT NULL,
    occurred_at        TIMESTAMPTZ NOT NULL,
    text               TEXT NOT NULL,
    author_id          UUID,
    source             TEXT,
    external_reference TEXT
);
CREATE INDEX ix_interactions_lead ON interactions (lead_id, occurred_at DESC);

CREATE TABLE contact_permissions (
    id           UUID PRIMARY KEY,
    created_at   TIMESTAMPTZ NOT NULL,
    updated_at   TIMESTAMPTZ NOT NULL,
    lead_id      UUID NOT NULL REFERENCES leads (id) ON DELETE CASCADE,
    workspace_id UUID NOT NULL REFERENCES workspaces (id),
    channel      TEXT NOT NULL,
    purpose      TEXT,
    status       TEXT NOT NULL,
    captured_at  TIMESTAMPTZ,
    source       TEXT,
    withdrawn_at TIMESTAMPTZ
);
CREATE INDEX ix_contact_permissions_lead ON contact_permissions (lead_id);

CREATE TABLE tasks (
    id           UUID PRIMARY KEY,
    created_at   TIMESTAMPTZ NOT NULL,
    updated_at   TIMESTAMPTZ NOT NULL,
    lead_id      UUID NOT NULL REFERENCES leads (id) ON DELETE CASCADE,
    workspace_id UUID NOT NULL REFERENCES workspaces (id),
    owner_id     UUID NOT NULL REFERENCES users (id),
    action       TEXT NOT NULL,
    due_at       TIMESTAMPTZ,
    status       TEXT NOT NULL,
    completed_at TIMESTAMPTZ
);
CREATE INDEX ix_tasks_workspace_status_due ON tasks (workspace_id, status, due_at);
CREATE INDEX ix_tasks_lead ON tasks (lead_id);

CREATE TABLE lead_stage_events (
    id           UUID PRIMARY KEY,
    created_at   TIMESTAMPTZ NOT NULL,
    updated_at   TIMESTAMPTZ NOT NULL,
    lead_id      UUID NOT NULL REFERENCES leads (id) ON DELETE CASCADE,
    workspace_id UUID NOT NULL REFERENCES workspaces (id),
    old_stage    TEXT,
    new_stage    TEXT NOT NULL,
    changed_at   TIMESTAMPTZ NOT NULL,
    author_id    UUID,
    reason       TEXT
);
CREATE INDEX ix_stage_events_lead ON lead_stage_events (lead_id, changed_at);

CREATE TABLE properties (
    id             UUID PRIMARY KEY,
    created_at     TIMESTAMPTZ NOT NULL,
    updated_at     TIMESTAMPTZ NOT NULL,
    workspace_id   UUID NOT NULL REFERENCES workspaces (id),
    external_id    TEXT,
    developer      TEXT,
    project        TEXT,
    unit_type      TEXT,
    location       TEXT,
    emirate        TEXT,
    community      TEXT,
    bedrooms       INTEGER,
    price_aed      NUMERIC(18, 2),
    size_sqft      NUMERIC(12, 2),
    amenities      JSONB,
    completion     TEXT,
    listing_status TEXT,
    sample         BOOLEAN NOT NULL DEFAULT FALSE
);
CREATE INDEX ix_properties_workspace ON properties (workspace_id);
CREATE INDEX ix_properties_match ON properties (workspace_id, sample, listing_status, bedrooms);

CREATE TABLE property_sources (
    id              UUID PRIMARY KEY,
    created_at      TIMESTAMPTZ NOT NULL,
    updated_at      TIMESTAMPTZ NOT NULL,
    property_id     UUID NOT NULL REFERENCES properties (id) ON DELETE CASCADE,
    workspace_id    UUID NOT NULL REFERENCES workspaces (id),
    approved_source TEXT,
    document_version TEXT,
    fetched_at      TIMESTAMPTZ,
    verified_at     TIMESTAMPTZ,
    verified_by     UUID,
    validity_status TEXT
);
CREATE INDEX ix_property_sources_property ON property_sources (property_id);

-- Structured payment terms. Optional until verified; no application entity in Milestone 1.
CREATE TABLE property_payment_terms (
    id             UUID PRIMARY KEY,
    created_at     TIMESTAMPTZ NOT NULL,
    updated_at     TIMESTAMPTZ NOT NULL,
    property_id    UUID NOT NULL REFERENCES properties (id) ON DELETE CASCADE,
    source_id      UUID REFERENCES property_sources (id),
    instalments    JSONB,
    due_events     JSONB,
    effective_date DATE
);

CREATE TABLE audit_events (
    id           UUID PRIMARY KEY,
    created_at   TIMESTAMPTZ NOT NULL,
    updated_at   TIMESTAMPTZ NOT NULL,
    workspace_id UUID NOT NULL REFERENCES workspaces (id),
    actor_id     UUID,
    operation    TEXT NOT NULL,
    result       TEXT NOT NULL,
    metadata     JSONB
);
CREATE INDEX ix_audit_workspace ON audit_events (workspace_id, created_at);

CREATE TABLE import_jobs (
    id              UUID PRIMARY KEY,
    created_at      TIMESTAMPTZ NOT NULL,
    updated_at      TIMESTAMPTZ NOT NULL,
    workspace_id    UUID NOT NULL REFERENCES workspaces (id),
    actor_id        UUID NOT NULL,
    idempotency_key TEXT NOT NULL,
    operation       TEXT NOT NULL,
    result          TEXT NOT NULL,
    summary         JSONB,
    CONSTRAINT uq_import_jobs_idem UNIQUE (workspace_id, idempotency_key)
);
